import { GAME_REGISTRY, GameMeta } from '../games/registry.ts';
import { LocalStorageAdapter } from '../storage/LocalStorageAdapter.ts';
import { Icons } from '../ui/icons.ts';

export class LobbyView {
  private container: HTMLElement;
  private storage: LocalStorageAdapter;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
    this.storage = new LocalStorageAdapter();
  }

  public async mount(): Promise<() => void> {
    const highScore = await this.storage.getHighScore();

    this.container.innerHTML = `
      <div class="lobby-view">
        <!-- Lobby Top Header -->
        <header class="lobby-header">
          <div class="lobby-brand">
            <img src="./assets/token/Snek-Round-BG.svg" alt="SNEK" class="brand-logo" />
            <div class="brand-text-col">
              <span class="brand-title">SNEK ARCADE</span>
              <span class="brand-badge">TAIWAN HUB</span>
            </div>
          </div>
          <div class="lobby-user-stats">
            <span class="lobby-stat-label">HIGH SCORE</span>
            <span class="lobby-stat-val">${highScore.toLocaleString()}</span>
          </div>
        </header>

        <!-- Scrollable Main Content -->
        <div class="lobby-scroll-content">
          <!-- Hero Feature Banner -->
          <section class="lobby-hero-card">
            <div class="hero-bg-wrapper">
              <img src="./assets/banner/Snek Banana 1200x630.webp" alt="Snek Hero" class="hero-bg-img" />
              <div class="hero-overlay"></div>
            </div>
            <div class="hero-content">
              <span class="hero-pill">
                ${Icons.flame}
                <span>FEATURED GAME</span>
              </span>
              <h2 class="hero-title">SNEK CLASSIC</h2>
              <p class="hero-desc">吃代幣變長，啟動 Burn Dash 燃燒衝刺！挑戰全台蛇友最高分並生成專屬迷因戰績卡。</p>
              <button id="btn-hero-play" class="btn-hero-cta">
                ${Icons.play}
                <span>即刻開玩 · PLAY NOW</span>
              </button>
            </div>
          </section>

          <!-- Section Title -->
          <div class="lobby-section-header">
            <h3 class="section-title">ALL GAMES / 所有遊戲</h3>
            <span class="section-count">${GAME_REGISTRY.length} 款小遊戲</span>
          </div>

          <!-- Game Cards Grid -->
          <div class="lobby-games-grid">
            ${GAME_REGISTRY.map((game) => this.renderGameCard(game)).join('')}
          </div>
        </div>

        <!-- Bottom Platform Navigation Bar -->
        <nav class="lobby-bottom-bar" aria-label="Platform Navigation">
          <button id="tab-lobby" class="lobby-tab-btn active">
            ${Icons.gamepad}
            <span>大廳</span>
          </button>
          <button id="tab-leaderboard" class="lobby-tab-btn">
            ${Icons.trophy}
            <span>排行榜</span>
          </button>
          <button id="tab-rewards" class="lobby-tab-btn">
            ${Icons.gift}
            <span>NFT 獎勵</span>
          </button>
        </nav>

        <!-- Coming Soon / Info Modal -->
        <div id="lobby-modal" class="modal-overlay">
          <div class="game-modal lobby-info-modal">
            <h2 id="lobby-modal-title" class="modal-title">COMING SOON</h2>
            <p id="lobby-modal-desc" class="lobby-modal-desc">此功能正在緊鑼密鼓籌備中！</p>
            <div class="modal-actions">
              <button id="btn-lobby-modal-close" class="btn-primary">
                <span>我知道了</span>
              </button>
            </div>
          </div>
        </div>
      </div>
    `;

    // Bind Hero Play
    const btnHeroPlay = this.container.querySelector('#btn-hero-play') as HTMLButtonElement;
    btnHeroPlay?.addEventListener('click', () => {
      window.location.hash = '#/game/snake';
    });

    // Bind Game Cards
    this.container.querySelectorAll('.game-card').forEach((card) => {
      const gameId = card.getAttribute('data-id');
      const isPlayable = card.getAttribute('data-status') === 'playable';

      card.addEventListener('click', () => {
        if (isPlayable) {
          window.location.hash = `#/game/${gameId}`;
        } else {
          const game = GAME_REGISTRY.find((g) => g.id === gameId);
          if (game) {
            this.showModal(
              game.title,
              `【${game.subtitle}】\n\n${game.description}\n\n狀態：${game.releaseDate || '籌備中'}，敬請鎖定 SNEK 社群第一手公告！`
            );
          }
        }
      });
    });

    // Bind Tab Bar
    const tabLeaderboard = this.container.querySelector('#tab-leaderboard') as HTMLButtonElement;
    tabLeaderboard?.addEventListener('click', () => {
      this.showModal(
        '🏆 全球排行榜系統',
        '第二階段（Phase 2）即將登場！\n\n將支援日榜、週榜與名人堂歷史殿堂，並整合防作弊驗證，敬請期待！'
      );
    });

    const tabRewards = this.container.querySelector('#tab-rewards') as HTMLButtonElement;
    tabRewards?.addEventListener('click', () => {
      this.showModal(
        '🎁 Cardano NFT 獎勵',
        '第三階段（Phase 3）即將登場！\n\n達到特定分數門檻與賽事冠軍者，將可連接 CIP-30 錢包直接鑄造 SNEK 限定成就 NFT！'
      );
    });

    // Bind Modal Close
    const modal = this.container.querySelector('#lobby-modal') as HTMLElement;
    const btnClose = this.container.querySelector('#btn-lobby-modal-close') as HTMLButtonElement;
    btnClose?.addEventListener('click', () => {
      modal.classList.remove('active');
    });

    return () => {
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }

  private renderGameCard(game: GameMeta): string {
    const isPlayable = game.status === 'playable';
    const badgeText = game.badge === 'HOT' ? 'HOT 🔥' : game.badge === 'NEW' ? 'NEW' : 'SOON';
    const badgeClass = game.badge.toLowerCase();

    return `
      <div class="game-card ${isPlayable ? 'playable' : 'coming-soon'}" data-id="${game.id}" data-status="${game.status}">
        <div class="game-card-header">
          <img src="${game.iconImg}" alt="${game.title}" class="game-card-icon" />
          <span class="game-card-badge ${badgeClass}">${badgeText}</span>
        </div>
        <div class="game-card-body">
          <h4 class="game-card-title">${game.title}</h4>
          <span class="game-card-subtitle">${game.subtitle}</span>
          <p class="game-card-desc">${game.description}</p>
          <div class="game-card-tags">
            ${game.tags.map((t) => `<span class="game-tag">#${t}</span>`).join('')}
          </div>
        </div>
        <div class="game-card-footer">
          <button class="btn-card-action ${isPlayable ? 'btn-play' : 'btn-soon'}">
            ${isPlayable ? Icons.play : Icons.sparkles}
            <span>${isPlayable ? 'PLAY NOW' : '玩法預告'}</span>
          </button>
        </div>
      </div>
    `;
  }

  private showModal(title: string, desc: string): void {
    const modal = this.container.querySelector('#lobby-modal') as HTMLElement;
    const modalTitle = this.container.querySelector('#lobby-modal-title') as HTMLElement;
    const modalDesc = this.container.querySelector('#lobby-modal-desc') as HTMLElement;

    if (modal && modalTitle && modalDesc) {
      modalTitle.textContent = title;
      modalDesc.innerHTML = desc.replace(/\n/g, '<br/>');
      modal.classList.add('active');
    }
  }
}
