import { GameEngine } from '../../engine/GameEngine.ts';
import { GameScoreRecord, GameState } from '../../types.ts';
import { Icons } from '../../ui/icons.ts';
import { ShareCardGenerator } from '../../ui/ShareCardGenerator.ts';

export class SnakeView {
  private container: HTMLElement;
  private engine: GameEngine | null = null;
  private cleanups: (() => void)[] = [];

  constructor(container: HTMLElement) {
    this.container = container;
  }

  public mount(): () => void {
    // 1. Render Template with "Back to Lobby" button
    this.container.innerHTML = `
      <div class="game-view snake-view">
        <!-- Arcade Header / HUD -->
        <header class="arcade-header">
          <div class="brand-section">
            <button id="btn-back-lobby" class="icon-btn back-btn" title="返回大廳" aria-label="返回大廳">
              ${Icons.back}
            </button>
            <span class="brand-title">SNEK</span>
          </div>

          <div class="hud-stats">
            <div class="stat-item">
              <span class="stat-label">SCORE</span>
              <span id="hud-score" class="stat-value score">0</span>
            </div>
            <div class="stat-item">
              <span class="stat-label">HIGH</span>
              <span id="hud-high-score" class="stat-value high-score">0</span>
            </div>
            <div class="stat-item length-stat">
              <span class="stat-label">LEN</span>
              <span id="hud-length" class="stat-value">4</span>
            </div>
          </div>

          <div class="hud-actions">
            <button id="btn-mode" class="icon-btn" title="切換按鍵 / 滑動模式" aria-label="切換模式">
              ${Icons.gamepad}
            </button>
            <button id="btn-audio" class="icon-btn" title="切換音效" aria-label="切換音效">
              ${Icons.volume}
            </button>
            <button id="btn-pause" class="icon-btn" title="暫停遊戲" aria-label="暫停遊戲">
              ${Icons.pause}
            </button>
          </div>
        </header>

        <!-- Main Game Canvas Container -->
        <main class="canvas-container">
          <div class="canvas-wrapper">
            <canvas id="game-canvas"></canvas>

            <!-- Game Over Modal -->
            <div id="gameover-modal" class="modal-overlay">
              <div class="game-modal">
                <h2 id="modal-title" class="modal-title">GAME OVER</h2>

                <div class="modal-stats-grid">
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">本次得分</span>
                    <span id="modal-score" class="modal-stat-val primary">0</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">歷史最高</span>
                    <span id="modal-high-score" class="modal-stat-val">0</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">蛇身長度</span>
                    <span id="modal-length" class="modal-stat-val">4</span>
                  </div>
                  <div class="modal-stat-box">
                    <span class="modal-stat-label">存活時間</span>
                    <span id="modal-time" class="modal-stat-val">0:00</span>
                  </div>
                </div>

                <div class="modal-actions">
                  <button id="btn-restart" class="btn-primary">
                    ${Icons.restart}
                    <span>PLAY AGAIN</span>
                  </button>
                  <div class="share-row">
                    <button id="btn-share-x" class="btn-secondary">
                      ${Icons.xLogo}
                      <span>SHARE TO X</span>
                    </button>
                    <button id="btn-download-card" class="btn-secondary">
                      ${Icons.camera}
                      <span>SAVE CARD</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </main>

        <!-- Mobile Ergonomic Dual-Thumb Control Deck -->
        <nav id="mobile-deck" class="mobile-control-deck" aria-label="Mobile Controls">
          <!-- Left: Cross D-Pad with Beveled Chevrons -->
          <div class="dpad-cross-container">
            <button id="ctrl-up" class="dpad-cross-btn dpad-up" aria-label="向上">
              ${Icons.chevronUp}
            </button>
            <div class="dpad-middle-row">
              <button id="ctrl-left" class="dpad-cross-btn dpad-left" aria-label="向左">
                ${Icons.chevronLeft}
              </button>
              <div class="dpad-center-core"></div>
              <button id="ctrl-right" class="dpad-cross-btn dpad-right" aria-label="向右">
                ${Icons.chevronRight}
              </button>
            </div>
            <button id="ctrl-down" class="dpad-cross-btn dpad-down" aria-label="向下">
              ${Icons.chevronDown}
            </button>
          </div>

          <!-- Right: Turbo Burn Dash Button with Gradient Flame -->
          <div class="turbo-btn-container">
            <button id="ctrl-boost" class="turbo-boost-btn" aria-label="燃燒衝刺">
              ${Icons.flame}
              <span class="boost-text">BOOST</span>
            </button>
          </div>
        </nav>

        <!-- Desktop-only instructions bar -->
        <footer class="desktop-instructions">
          <span><span class="key-badge">WASD / ARROWS</span> MOVE</span>
          <span><span class="key-badge">SPACE</span> BURN DASH</span>
          <span><span class="key-badge">P</span> PAUSE</span>
          <span><span class="key-badge">R</span> RESTART</span>
        </footer>
      </div>
    `;

    // 2. Select Elements
    const canvas = this.container.querySelector('#game-canvas') as HTMLCanvasElement;
    const canvasWrapper = this.container.querySelector('.canvas-wrapper') as HTMLElement;
    const mobileDeck = this.container.querySelector('#mobile-deck') as HTMLElement;
    const btnBack = this.container.querySelector('#btn-back-lobby') as HTMLButtonElement;

    const hudScore = this.container.querySelector('#hud-score') as HTMLElement;
    const hudHighScore = this.container.querySelector('#hud-high-score') as HTMLElement;
    const hudLength = this.container.querySelector('#hud-length') as HTMLElement;
    const btnMode = this.container.querySelector('#btn-mode') as HTMLButtonElement;
    const btnAudio = this.container.querySelector('#btn-audio') as HTMLButtonElement;
    const btnPause = this.container.querySelector('#btn-pause') as HTMLButtonElement;

    const modalOverlay = this.container.querySelector('#gameover-modal') as HTMLElement;
    const modalTitle = this.container.querySelector('#modal-title') as HTMLElement;
    const modalScore = this.container.querySelector('#modal-score') as HTMLElement;
    const modalHighScore = this.container.querySelector('#modal-high-score') as HTMLElement;
    const modalLength = this.container.querySelector('#modal-length') as HTMLElement;
    const modalTime = this.container.querySelector('#modal-time') as HTMLElement;
    const btnRestart = this.container.querySelector('#btn-restart') as HTMLButtonElement;
    const btnShareX = this.container.querySelector('#btn-share-x') as HTMLButtonElement;
    const btnDownloadCard = this.container.querySelector('#btn-download-card') as HTMLButtonElement;

    const ctrlUp = this.container.querySelector('#ctrl-up') as HTMLButtonElement;
    const ctrlDown = this.container.querySelector('#ctrl-down') as HTMLButtonElement;
    const ctrlLeft = this.container.querySelector('#ctrl-left') as HTMLButtonElement;
    const ctrlRight = this.container.querySelector('#ctrl-right') as HTMLButtonElement;
    const ctrlBoost = this.container.querySelector('#ctrl-boost') as HTMLButtonElement;

    let lastRecord: GameScoreRecord | null = null;

    // 3. Back to Lobby Handler
    btnBack.addEventListener('click', () => {
      window.location.hash = '#/';
    });

    // 4. Initialize Game Engine
    this.engine = new GameEngine(canvas, {
      onScoreUpdate: (score: number, highScore: number, length: number) => {
        hudScore.textContent = score.toLocaleString();
        hudHighScore.textContent = highScore.toLocaleString();
        hudLength.textContent = length.toString();
      },
      onStateChange: (state: GameState, record?: GameScoreRecord) => {
        if (state === 'GAME_OVER' && record) {
          lastRecord = record;
          const isNewRecord = record.score > 0 && record.score >= record.highScore;

          modalTitle.textContent = isNewRecord ? 'NEW HIGH SCORE!' : 'GAME OVER';
          modalTitle.className = isNewRecord ? 'modal-title new-record' : 'modal-title';

          modalScore.textContent = record.score.toLocaleString();
          modalHighScore.textContent = record.highScore.toLocaleString();
          modalLength.textContent = record.length.toString();

          const mins = Math.floor(record.durationSeconds / 60);
          const secs = record.durationSeconds % 60;
          modalTime.textContent = `${mins}:${secs < 10 ? '0' : ''}${secs}`;

          modalOverlay.classList.add('active');
        } else {
          modalOverlay.classList.remove('active');
        }

        if (state === 'PAUSED') {
          btnPause.innerHTML = Icons.play;
        } else {
          btnPause.innerHTML = Icons.pause;
        }
      },
    });

    const engine = this.engine;

    // Sound toggle
    const updateAudioBtn = () => {
      btnAudio.innerHTML = engine.soundManager.isMuted() ? Icons.volumeMute : Icons.volume;
    };
    updateAudioBtn();

    btnAudio.addEventListener('click', (e) => {
      e.stopPropagation();
      engine.soundManager.toggleMute();
      updateAudioBtn();
    });

    // Control Mode Toggle
    let isSwipeOnlyMode = localStorage.getItem('snek_ctrl_mode') === 'swipe';
    const updateModeBtn = () => {
      if (isSwipeOnlyMode) {
        btnMode.innerHTML = Icons.swipe;
        btnMode.title = '目前：全螢幕滑動手勢 (點擊切換為按鍵)';
        mobileDeck.classList.add('deck-hidden');
      } else {
        btnMode.innerHTML = Icons.gamepad;
        btnMode.title = '目前：雙手按鍵模式 (點擊切換為純滑動)';
        mobileDeck.classList.remove('deck-hidden');
      }
    };
    updateModeBtn();

    btnMode.addEventListener('click', (e) => {
      e.stopPropagation();
      isSwipeOnlyMode = !isSwipeOnlyMode;
      localStorage.setItem('snek_ctrl_mode', isSwipeOnlyMode ? 'swipe' : 'dpad');
      updateModeBtn();
    });

    btnPause.addEventListener('click', (e) => {
      e.stopPropagation();
      engine.togglePause();
    });

    btnRestart.addEventListener('click', (e) => {
      e.stopPropagation();
      modalOverlay.classList.remove('active');
      engine.start();
    });

    btnShareX.addEventListener('click', (e) => {
      e.stopPropagation();
      if (lastRecord) {
        ShareCardGenerator.shareToTwitter(lastRecord.score, lastRecord.length);
      }
    });

    btnDownloadCard.addEventListener('click', async (e) => {
      e.stopPropagation();
      if (lastRecord) {
        const cardCanvas = await ShareCardGenerator.generateCard(
          lastRecord.score,
          lastRecord.length,
          lastRecord.durationSeconds
        );
        ShareCardGenerator.downloadCanvas(cardCanvas, `snek-score-${lastRecord.score}.png`);
      }
    });

    // Touch Swipe
    engine.inputManager.bindTouchSwipe(canvasWrapper);

    // Cross D-Pad
    const bindDirectionBtn = (btn: HTMLElement, dir: 'UP' | 'DOWN' | 'LEFT' | 'RIGHT') => {
      btn.addEventListener(
        'touchstart',
        (e) => {
          e.preventDefault();
          e.stopPropagation();
          engine.handleDirection(dir);
          btn.classList.add('active');
        },
        { passive: false }
      );

      const removeActive = () => btn.classList.remove('active');
      btn.addEventListener('touchend', removeActive, { passive: true });
      btn.addEventListener('touchcancel', removeActive, { passive: true });

      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        engine.handleDirection(dir);
      });
    };

    bindDirectionBtn(ctrlUp, 'UP');
    bindDirectionBtn(ctrlDown, 'DOWN');
    bindDirectionBtn(ctrlLeft, 'LEFT');
    bindDirectionBtn(ctrlRight, 'RIGHT');

    // Turbo Boost
    const startBoost = (e: Event) => {
      e.preventDefault();
      e.stopPropagation();
      ctrlBoost.classList.add('active');
      engine.handleBoost(true);
    };
    const endBoost = (e: Event) => {
      e.preventDefault();
      e.stopPropagation();
      ctrlBoost.classList.remove('active');
      engine.handleBoost(false);
    };

    ctrlBoost.addEventListener('touchstart', startBoost, { passive: false });
    ctrlBoost.addEventListener('touchend', endBoost, { passive: false });
    ctrlBoost.addEventListener('touchcancel', endBoost, { passive: false });
    ctrlBoost.addEventListener('mousedown', startBoost);
    ctrlBoost.addEventListener('mouseup', endBoost);
    ctrlBoost.addEventListener('mouseleave', endBoost);

    canvasWrapper.addEventListener('click', () => {
      engine.soundManager.unlock();
      if (engine.state === 'READY') {
        engine.start();
      }
    });

    // Return unmount cleanup
    return () => {
      if (this.engine) {
        this.engine.destroy();
        this.engine = null;
      }
      this.cleanups.forEach((c) => c());
      this.cleanups = [];
      this.container.innerHTML = '';
    };
  }
}
