import { Particle } from '../types.ts';

export class ParticleSystem {
  private particles: Particle[] = [];

  public update(dt: number): void {
    const timeScale = dt / 16.66; // normalize to 60fps
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx * timeScale;
      p.y += p.vy * timeScale;
      p.alpha -= p.decay * timeScale;
      p.size = Math.max(0, p.size - 0.05 * timeScale);

      if (p.alpha <= 0 || p.size <= 0) {
        this.particles.splice(i, 1);
      }
    }
  }

  public render(ctx: CanvasRenderingContext2D): void {
    if (this.particles.length === 0) return;

    ctx.save();
    for (const p of this.particles) {
      ctx.globalAlpha = Math.max(0, Math.min(1, p.alpha));
      ctx.fillStyle = p.color;

      if (p.shape === 'square') {
        ctx.fillRect(p.x - p.size / 2, p.y - p.size / 2, p.size, p.size);
      } else {
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fill();
      }
    }
    ctx.restore();
  }

  /**
   * 普通 SNEK 金幣綠色霓虹粒子
   */
  public emitEat(x: number, y: number): void {
    const count = 16;
    for (let i = 0; i < count; i++) {
      const angle = (Math.PI * 2 * i) / count + (Math.random() - 0.5) * 0.5;
      const speed = 1.5 + Math.random() * 3.5;
      this.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: 2.5 + Math.random() * 3.5,
        color: Math.random() > 0.3 ? '#00e676' : '#69f0ae',
        alpha: 1,
        decay: 0.03 + Math.random() * 0.02,
        shape: Math.random() > 0.5 ? 'circle' : 'square',
      });
    }
  }

  /**
   * 稀有 ADA 金色/青色爆發粒子
   */
  public emitSuperEat(x: number, y: number): void {
    const count = 28;
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 2 + Math.random() * 5;
      this.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: 3 + Math.random() * 4,
        color: Math.random() > 0.4 ? '#ffd700' : '#00b0ff',
        alpha: 1,
        decay: 0.02 + Math.random() * 0.015,
        shape: 'spark',
      });
    }
  }

  /**
   * 燃燒衝刺尾跡火焰
   */
  public emitBurnDash(x: number, y: number, angleRad: number): void {
    const count = 3;
    for (let i = 0; i < count; i++) {
      // Emit backwards relative to movement
      const spread = (Math.random() - 0.5) * 0.8;
      const backAngle = angleRad + Math.PI + spread;
      const speed = 1 + Math.random() * 2.5;
      this.particles.push({
        x: x + (Math.random() - 0.5) * 8,
        y: y + (Math.random() - 0.5) * 8,
        vx: Math.cos(backAngle) * speed,
        vy: Math.sin(backAngle) * speed,
        size: 2 + Math.random() * 3,
        color: Math.random() > 0.5 ? '#ff9100' : '#ff3d00',
        alpha: 0.9,
        decay: 0.05 + Math.random() * 0.03,
        shape: 'circle',
      });
    }
  }

  /**
   * 陣亡破裂粒子
   */
  public emitDeath(x: number, y: number): void {
    const count = 35;
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 2 + Math.random() * 6;
      this.particles.push({
        x,
        y,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        size: 3 + Math.random() * 5,
        color: Math.random() > 0.5 ? '#ff1744' : '#00e676',
        alpha: 1,
        decay: 0.025 + Math.random() * 0.02,
        shape: 'square',
      });
    }
  }

  public clear(): void {
    this.particles = [];
  }
}
