import confetti from 'canvas-confetti';
import { SoundManager } from '../audio/SoundManager.ts';
import { LocalStorageAdapter } from '../storage/LocalStorageAdapter.ts';
import { StorageAdapter } from '../storage/StorageAdapter.ts';
import { Direction, GameScoreRecord, GameState } from '../types.ts';
import { FoodManager } from './FoodManager.ts';
import { InputManager } from './InputManager.ts';
import { ParticleSystem } from './ParticleSystem.ts';
import { Snake } from './Snake.ts';

export interface GameEngineCallbacks {
  onScoreUpdate: (score: number, highScore: number, length: number) => void;
  onStateChange: (state: GameState, record?: GameScoreRecord) => void;
}

export class GameEngine {
  public canvas: HTMLCanvasElement;
  public ctx: CanvasRenderingContext2D;
  private callbacks: GameEngineCallbacks;

  // Grid Configuration
  public readonly gridWidth: number = 24;
  public readonly gridHeight: number = 24;
  public cellSize: number = 25; // 600 x 600 base
  private logicalWidth: number = 600;
  private logicalHeight: number = 600;

  // Systems
  public snake: Snake;
  public foodManager: FoodManager;
  public particleSystem: ParticleSystem;
  public soundManager: SoundManager;
  public storage: StorageAdapter;
  public inputManager: InputManager;

  // State
  public state: GameState = 'READY';
  public score: number = 0;
  public highScore: number = 0;
  public isBoosting: boolean = false;
  private foodsEaten: number = 0;
  private startTimeMs: number = 0;
  private durationSeconds: number = 0;

  // Loop & Timing
  private lastTime: number = 0;
  private moveTimer: number = 0;
  private screenShakeTime: number = 0;
  private screenShakeIntensity: number = 0;
  private boostDrainTimer: number = 0;
  private animationFrameId: number | null = null;

  constructor(canvas: HTMLCanvasElement, callbacks: GameEngineCallbacks) {
    this.canvas = canvas;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('Cannot get 2D context');
    this.ctx = ctx;
    this.callbacks = callbacks;

    this.snake = new Snake({ x: 8, y: 12 }, 4);
    this.foodManager = new FoodManager(this.gridWidth, this.gridHeight);
    this.particleSystem = new ParticleSystem();
    this.soundManager = new SoundManager();
    this.storage = new LocalStorageAdapter();

    this.inputManager = new InputManager({
      onDirection: (dir: Direction) => this.handleDirection(dir),
      onBoostChange: (boosting: boolean) => this.handleBoost(boosting),
      onPauseToggle: () => this.togglePause(),
      onRestart: () => this.start(),
    });

    this.initCanvasSize();
    this.loadHighScore();
    this.startLoop();
  }

  private initCanvasSize(): void {
    this.logicalWidth = this.gridWidth * this.cellSize;
    this.logicalHeight = this.gridHeight * this.cellSize;

    // Handle Retina / Hi-DPI
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = this.logicalWidth * dpr;
    this.canvas.height = this.logicalHeight * dpr;
    this.ctx.scale(dpr, dpr);
  }

  private async loadHighScore(): Promise<void> {
    this.highScore = await this.storage.getHighScore();
    this.callbacks.onScoreUpdate(this.score, this.highScore, this.snake.segments.length);
  }

  public handleDirection(dir: Direction): void {
    if (this.state === 'READY') {
      this.start();
    }
    if (this.state === 'PLAYING') {
      this.soundManager.unlock();
      this.snake.queueDirection(dir);
    }
  }

  public handleBoost(boosting: boolean): void {
    if (this.state !== 'PLAYING') {
      this.isBoosting = false;
      return;
    }
    // Only boost if score is at least 5 to prevent cheating
    if (boosting && this.score > 0) {
      this.isBoosting = true;
      this.soundManager.playBoost();
    } else {
      this.isBoosting = false;
    }
  }

  public togglePause(): void {
    if (this.state === 'PLAYING') {
      this.state = 'PAUSED';
      this.callbacks.onStateChange(this.state);
    } else if (this.state === 'PAUSED') {
      this.state = 'PLAYING';
      this.lastTime = performance.now();
      this.callbacks.onStateChange(this.state);
    }
  }

  public start(): void {
    this.soundManager.unlock();
    this.score = 0;
    this.foodsEaten = 0;
    this.isBoosting = false;
    this.startTimeMs = performance.now();
    this.durationSeconds = 0;
    this.moveTimer = 0;
    this.screenShakeTime = 0;
    this.boostDrainTimer = 0;

    this.snake.reset({ x: 8, y: 12 }, 4);
    this.foodManager.reset(this.snake.segments);
    this.particleSystem.clear();

    this.state = 'PLAYING';
    this.lastTime = performance.now();
    this.callbacks.onScoreUpdate(this.score, this.highScore, this.snake.segments.length);
    this.callbacks.onStateChange(this.state);
  }

  private async handleGameOver(): Promise<void> {
    this.state = 'GAME_OVER';
    this.snake.state = 'dead';
    this.isBoosting = false;

    // Trigger death sound & vibration
    this.soundManager.playDie();
    this.inputManager.vibrate([60, 40, 100]);
    this.triggerScreenShake(400, 10);
    this.particleSystem.emitDeath(
      this.snake.head.x * this.cellSize + this.cellSize / 2,
      this.snake.head.y * this.cellSize + this.cellSize / 2
    );

    this.durationSeconds = Math.floor((performance.now() - this.startTimeMs) / 1000);

    const record: GameScoreRecord = {
      score: this.score,
      highScore: Math.max(this.score, this.highScore),
      length: this.snake.segments.length,
      durationSeconds: this.durationSeconds,
      foodsEaten: this.foodsEaten,
      date: new Date().toISOString(),
    };

    const result = await this.storage.saveScore(record);
    if (result.isNewHighScore && this.score > 0) {
      this.highScore = this.score;
      this.soundManager.playHighScore();
      // Victory confetti!
      confetti({
        particleCount: 80,
        spread: 70,
        origin: { y: 0.6 },
        colors: ['#00e676', '#ffd700', '#00b0ff'],
      });
    }

    this.callbacks.onScoreUpdate(this.score, this.highScore, this.snake.segments.length);
    this.callbacks.onStateChange(this.state, record);
  }

  private triggerScreenShake(durationMs: number, intensity: number): void {
    this.screenShakeTime = durationMs;
    this.screenShakeIntensity = intensity;
  }

  private getTickInterval(): number {
    // Dynamic difficulty: speed up as score rises
    const baseSpeed = 120; // ms
    const speedUp = Math.min(50, Math.floor(this.score / 30) * 5);
    let interval = baseSpeed - speedUp;

    if (this.isBoosting) {
      interval = Math.max(45, interval / 1.7);
    }
    return Math.max(50, interval);
  }

  private startLoop(): void {
    const loop = (timestamp: number) => {
      if (!this.lastTime) this.lastTime = timestamp;
      const dt = timestamp - this.lastTime;
      this.lastTime = timestamp;

      this.update(dt);
      this.render();

      this.animationFrameId = requestAnimationFrame(loop);
    };

    this.lastTime = performance.now();
    this.animationFrameId = requestAnimationFrame(loop);
  }

  public destroy(): void {
    if (this.animationFrameId !== null) {
      cancelAnimationFrame(this.animationFrameId);
    }
  }

  private update(dt: number): void {
    this.particleSystem.update(dt);

    if (this.screenShakeTime > 0) {
      this.screenShakeTime -= dt;
      if (this.screenShakeTime <= 0) {
        this.screenShakeTime = 0;
      }
    }

    if (this.state !== 'PLAYING') {
      return;
    }

    this.snake.update(dt, this.isBoosting);
    this.foodManager.update(dt, this.snake.segments, this.score);

    // Burn Dash boost fuel drain: consumes 1 point every 2 seconds
    if (this.isBoosting) {
      this.boostDrainTimer += dt;
      // Emit flame particles from head
      const hx = this.snake.head.x * this.cellSize + this.cellSize / 2;
      const hy = this.snake.head.y * this.cellSize + this.cellSize / 2;
      this.particleSystem.emitBurnDash(hx, hy, this.snake.getAngle());

      if (this.boostDrainTimer >= 2000) {
        this.boostDrainTimer = 0;
        if (this.score > 0) {
          this.score = Math.max(0, this.score - 1);
          this.callbacks.onScoreUpdate(this.score, this.highScore, this.snake.segments.length);
        } else {
          this.isBoosting = false;
        }
      }
    }

    // Fixed timestep step tick
    this.moveTimer += dt;
    const interval = this.getTickInterval();

    if (this.moveTimer >= interval) {
      this.moveTimer = 0;
      this.step();
    }
  }

  private step(): void {
    const newHead = this.snake.move();

    // 1. Check Wall Collision
    if (
      newHead.x < 0 ||
      newHead.x >= this.gridWidth ||
      newHead.y < 0 ||
      newHead.y >= this.gridHeight
    ) {
      this.handleGameOver();
      return;
    }

    // 2. Check Self Collision
    if (this.snake.checkSelfCollision()) {
      this.handleGameOver();
      return;
    }

    // 3. Check Food Collision
    const eaten = this.foodManager.checkCollision(newHead);
    if (eaten) {
      this.score += eaten.points;
      this.foodsEaten++;
      this.snake.grow(eaten.growth);
      this.snake.setEating(300);

      const hx = newHead.x * this.cellSize + this.cellSize / 2;
      const hy = newHead.y * this.cellSize + this.cellSize / 2;

      if (eaten.type === 'ada_gem') {
        this.soundManager.playAda();
        this.inputManager.vibrate([20, 30, 20]);
        this.particleSystem.emitSuperEat(hx, hy);
        this.triggerScreenShake(200, 6);
      } else {
        this.soundManager.playEat();
        this.inputManager.vibrate(12);
        this.particleSystem.emitEat(hx, hy);
      }

      this.callbacks.onScoreUpdate(this.score, this.highScore, this.snake.segments.length);
    }
  }

  private render(): void {
    const ctx = this.ctx;
    ctx.save();

    // Screen Shake Offset
    if (this.screenShakeTime > 0) {
      const shakeFactor = this.screenShakeTime / 400;
      const ox = (Math.random() - 0.5) * this.screenShakeIntensity * shakeFactor;
      const oy = (Math.random() - 0.5) * this.screenShakeIntensity * shakeFactor;
      ctx.translate(ox, oy);
    }

    // 1. Clear background
    ctx.fillStyle = '#0a0e14';
    ctx.fillRect(0, 0, this.logicalWidth, this.logicalHeight);

    // 2. Draw Subtle Cyber Grid
    ctx.strokeStyle = 'rgba(0, 230, 118, 0.04)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= this.logicalWidth; x += this.cellSize) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, this.logicalHeight);
      ctx.stroke();
    }
    for (let y = 0; y <= this.logicalHeight; y += this.cellSize) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(this.logicalWidth, y);
      ctx.stroke();
    }

    // 3. Draw Neon Border
    ctx.strokeStyle = this.isBoosting ? '#ff3d00' : '#00e676';
    ctx.lineWidth = 3;
    ctx.shadowColor = this.isBoosting ? '#ff3d00' : '#00e676';
    ctx.shadowBlur = this.isBoosting ? 18 : 10;
    ctx.strokeRect(1.5, 1.5, this.logicalWidth - 3, this.logicalHeight - 3);
    ctx.shadowBlur = 0;

    // 4. Render Game Objects
    this.particleSystem.render(ctx);
    this.foodManager.render(ctx, this.cellSize);
    this.snake.render(ctx, this.cellSize, this.isBoosting);

    // 5. Render States Overlay
    if (this.state === 'READY') {
      this.renderReadyOverlay(ctx);
    } else if (this.state === 'PAUSED') {
      this.renderPausedOverlay(ctx);
    }

    ctx.restore();
  }

  private renderReadyOverlay(ctx: CanvasRenderingContext2D): void {
    ctx.fillStyle = 'rgba(10, 14, 20, 0.75)';
    ctx.fillRect(0, 0, this.logicalWidth, this.logicalHeight);

    ctx.textAlign = 'center';

    // Title
    ctx.fillStyle = '#00e676';
    ctx.shadowColor = '#00e676';
    ctx.shadowBlur = 18;
    ctx.font = '900 42px "Courier New", monospace, sans-serif';
    ctx.fillText('SNEK ARCADE', this.logicalWidth / 2, this.logicalHeight / 2 - 40);
    ctx.shadowBlur = 0;

    // Subtitle
    ctx.fillStyle = '#ffffff';
    ctx.font = 'bold 18px monospace';
    ctx.fillText('PRESS SPACE / ARROWS TO PLAY', this.logicalWidth / 2, this.logicalHeight / 2 + 15);

    ctx.fillStyle = '#8b949e';
    ctx.font = '14px monospace';
    ctx.fillText('HOLD SPACE OR BOOST: BURN DASH', this.logicalWidth / 2, this.logicalHeight / 2 + 55);
  }

  private renderPausedOverlay(ctx: CanvasRenderingContext2D): void {
    ctx.fillStyle = 'rgba(10, 14, 20, 0.7)';
    ctx.fillRect(0, 0, this.logicalWidth, this.logicalHeight);

    ctx.textAlign = 'center';
    ctx.fillStyle = '#ffd700';
    ctx.shadowColor = '#ffd700';
    ctx.shadowBlur = 15;
    ctx.font = 'bold 36px monospace';
    ctx.fillText('GAME PAUSED', this.logicalWidth / 2, this.logicalHeight / 2);
    ctx.shadowBlur = 0;

    ctx.fillStyle = '#ffffff';
    ctx.font = '16px monospace';
    ctx.fillText('PRESS P OR ESC TO RESUME', this.logicalWidth / 2, this.logicalHeight / 2 + 45);
  }
}
